/* estilo.css */
#erros-js {
    display: none;
}

// validacao.js, quando há erros
caixa.style.display = 'block';

/* CSS */
.msg ul { padding-left: 20px; }
ul.msg { padding-left: 36px; }

<!-- HTML -->
<div class="msg erro">
    <ul>
        <li>O título é obrigatório.</li>
    </ul>
</div>

/* CSS */
.btn { background: #00713c; }
.btn .perigo { background: #c0392b; }

<!-- HTML -->
<a href="..." class="btn perigo">Apagar</a>

#total    { color: green; }
.destaque { color: blue; }
p         { color: red; }

/* mais acima no ficheiro */
.cartao {
    background: #ffffff;
    border-radius: 8px;
    padding: 18px;
}

/* no fim do ficheiro */
.cartao {
    background: #eeeeee;
}

/* CSS */
.msg      { padding: 12px 16px; border-left: 5px solid; }
.msg.erro { background: #fdecea; }
#erros-js { display: none; }

<!-- HTML -->
<div id="erros-js" class="msg erro"></div>

.topo {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.detalhe dl {
    display: flex;
    flex-wrap: wrap;
}
.detalhe dt { width: 140px; }
.detalhe dd { width: calc(100% - 140px); margin: 0; }

.topo {
    display: flex;
    padding: 14px 32px;
}

/* ... no fim do ficheiro ... */
@media (max-width: 600px) {
    .topo {
        padding: 12px 16px;
    }
}

/* fora da media query */
.cartoes { display: flex; flex-wrap: wrap; gap: 16px; }
.cartao  { flex: 1 1 260px; }

/* a media query do fim do ficheiro */
@media (max-width: 600px) {
    .topo { padding: 12px 16px; }
    .topo nav { gap: 12px; font-size: 0.95rem; }
    .topo .ola { display: none; }
    .pesquisa input { min-width: 0; flex: 1; }
    .detalhe dt,
    .detalhe dd { width: 100%; }
}

/* fora */
.pesquisa input { min-width: 240px; }

@media (max-width: 600px) {
    .pesquisa input {
        min-width: 0;
        flex: 1;
    }
}

.detalhe dt { width: 140px; }
.detalhe dd { width: calc(100% - 140px); }

@media (max-width: 600px) {
    .detalhe dt,
    .detalhe dd {
        width: 100%;
    }
}
